import {EXPANSION_PACKS} from './race-packs.js';
import {DWARF_MATERIALS,DWARF_MATERIAL_REGISTRY,rollMonsterMaterials as rollDwarfMaterials,toDwarfInventoryKey,getDwarfMaterialPool,resolveDwarfMaterialId} from './dwarf-material-catalog.js';
import {lootOccurrenceProbability} from './luck-policy.js';
export const RACIAL_MATERIALS=Object.freeze(Object.assign({},...EXPANSION_PACKS.map(p=>p.materials)));
export const WORLD_MATERIALS=Object.freeze({...DWARF_MATERIALS,...RACIAL_MATERIALS});
export const WORLD_MATERIAL_REGISTRY=Object.freeze({...DWARF_MATERIAL_REGISTRY,...Object.fromEntries(Object.entries(RACIAL_MATERIALS).map(([key,m])=>[key,{...m,catalogId:key,origin:m.race??key.split('.')[0],merchantAllowed:!m.storyOnly&&!m.uniqueHeld,merchantBasePrice:m.merchantBasePrice??({'常见':3,'少见':8,'珍奇':18}[m.rarity]??8)}]))});
export function worldMaterialId(key){return Object.hasOwn(RACIAL_MATERIALS,key)?key:resolveDwarfMaterialId(key);}
export function worldInventoryKey(id){return Object.hasOwn(RACIAL_MATERIALS,id)?id:toDwarfInventoryKey(id);}
export function getWorldMaterialPool(monsterId,nodeId){return getDwarfMaterialPool(monsterId,nodeId)??EXPANSION_PACKS.find(p=>p.id===monsterId?.split('.')[0])?.materialPools?.[monsterId+'|'+nodeId]??null;}
export function validWorldMaterialPool(pool){return !!pool&&Array.isArray(pool.channels)&&pool.channels.every(c=>Number.isFinite(c.hitProbability)&&c.hitProbability>=0&&c.hitProbability<=1&&Number.isInteger(c.quantity)&&c.quantity>=1&&Array.isArray(c.entries)&&c.entries.every(e=>{const m=WORLD_MATERIALS[e.materialId];return m&&!m.storyOnly&&m.sources.includes(pool.nodeId)&&Number.isFinite(e.weight)&&e.weight>=0&&Array.isArray(e.qualityWeights)&&e.qualityWeights.length===4&&e.qualityWeights.every(x=>Number.isFinite(x)&&x>=0)&&Math.abs(e.qualityWeights.reduce((a,b)=>a+b,0)-1)<1e-8;})&&(c.entries.length?Math.abs(c.entries.reduce((a,e)=>a+e.weight,0)-1)<1e-8:c.hitProbability===0));}
export function rollWorldMaterials(s,e,unit,options={}){const monsterId=unit?.definitionId??unit?.monsterId;if(monsterId?.startsWith('dwarf.'))return rollDwarfMaterials(s,e,unit,options);const {random,rollQuality,owned,receive,luck=0}=options,nodeId=unit?.sourceInstanceId??e?.instanceId,pool=getWorldMaterialPool(monsterId,nodeId);if(unit?.origin==='summoned'||unit?.independentRewards===false||!validWorldMaterialPool(pool)||![random,rollQuality,owned,receive].every(f=>typeof f==='function'))return {ok:false,reason:'source',drops:[]};const drops=[];for(const c of pool.channels){if(!c.entries.length||random()>=lootOccurrenceProbability(c.hitProbability,luck))continue;let pick=random(),chosen=c.entries.at(-1);for(const row of c.entries){pick-=row.weight;if(pick<0){chosen=row;break;}}const m=WORLD_MATERIALS[chosen.materialId];for(let i=0;i<c.quantity;i++){if(m.uniqueHeld&&owned(s,m.id))break;const quality=m.uniqueHeld?3:rollQuality([...chosen.qualityWeights],luck,random);if(!Number.isInteger(quality)||quality<0||quality>3)throw Error('Invalid racial material quality');const row={materialId:m.id,material:worldInventoryKey(m.id),quality,quantity:1,channel:c.channel,monsterId,nodeId};drops.push({...row,received:receive(s,row)});}}return {ok:true,drops};}
